'use strict';
const DATA=window.STUDY;
const KEY=PROFILE_PREFIX+PROFILE_NAME;
let state={attempts:{},learned:[],settings:{mode:'study',minutes:120}};
let storageOkay=true;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved)state={...state,...saved,settings:{...state.settings,...saved.settings}};}catch(e){storageOkay=false;}
let query='',domain='all',referenceQuery='',lessonIndex=0,reviewFilter='wrong';
let activeQuiz=null;
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const letters=i=>String.fromCharCode(65+i);
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){storageOkay=false;}}
function getTest(id){return DATA.tests.find(t=>t.id===Number(id));}
function same(a,b,ordered=false){if(!Array.isArray(a)||a.length!==b.length)return false;return (ordered?a:[...a].sort((x,y)=>x-y)).every((v,i)=>v===(ordered?b:[...b].sort((x,y)=>x-y))[i]);}
function correct(q,a){return same(a,q.correct,q.type==='matching'||q.type==='ordering');}
function answered(q,a){if(!Array.isArray(a))return false;return q.type==='matching'||q.type==='ordering'?a.length===q.correct.length&&a.every(x=>Number.isInteger(x)&&x>=0):a.length>0;}
function elapsed(at){return Math.max(0,at.remaining-(at.runningSince?Math.floor((Date.now()-at.runningSince)/1000):0));}
function pause(){if(activeQuiz){const at=state.attempts[activeQuiz];if(at&&at.runningSince){at.remaining=elapsed(at);at.runningSince=null;save();}activeQuiz=null;}}
function score(t,at){const grade=t.questions.filter(q=>!q.unscored);const right=grade.filter(q=>correct(q,at.answers[q.id])).length;const assisted=grade.filter(q=>at.seen[q.id]).length;return {right,total:grade.length,percent:Math.round(right/grade.length*100),scaled:Math.round(100+900*right/grade.length),assisted,answered:t.questions.filter(q=>answered(q,at.answers[q.id])).length};}
function nav(to){location.hash=to;}
function frame(section,body){const learned=state.learned.length;const done=Object.values(state.attempts).filter(a=>a.finished).length;
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brandmark">AI</div><div><strong>AWS AI<br>Practitioner</strong><small>AWS · AIF-C01</small></div></div><div class="navlabel">Your workspace</div><nav aria-label="Main navigation">${[['learn','▤','Learn'],['practice','▣','Practice'],['review','◷','Review'],['sources','◇','Sources']].map(([key,icon,label])=>`<button class="navbutton ${section===key?'active':''}" data-act="nav" data-to="${key}" ${section===key?'aria-current="page"':''}><span class="navicon" aria-hidden="true">${icon}</span>${label}</button>`).join('')}</nav><div class="sidebottom"><strong>${learned}<span class="small"> / 65</span></strong><p>deep dives marked understood</p><div class="progress"><span style="width:${learned/65*100}%"></span></div><p style="margin-top:15px">${done} of 10 tests completed</p><p class="tiny">Profile: ${esc(PROFILE_NAME)} · saved on this browser.<br><button class="btn secondary small" data-profile-panel>My profile &amp; backup</button></p></div></aside><div class="workspace"><header class="topbar"><span class="crumb">AWS Certified AI Practitioner <span aria-hidden="true">/</span> ${esc(section[0].toUpperCase()+section.slice(1))}</span><span class="status">Official scope checked · 29 Sep 2026</span></header><main class="content" id="main">${!storageOkay?'<p class="notice" role="alert">Browser storage is unavailable. Keep this page open to retain this session; progress cannot be restored after closing.</p>':''}${body}<footer class="footer">Independent study material, not official AWS exam questions. Scores shown are estimates, not official AWS scaled scores. <a href="#sources">Exam guide and references</a></footer></main></div></div>`;
}
function head(eyebrow,title,text,extra=''){return `<div class="pagehead"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="muted">${text}</p></div>${extra}</div>`;}
function learn(){frame('learn',head('Understand, then apply','Learn through examples','Choose an exam domain, then study its concepts and worked examples.',`<a class="btn secondary small" href="study-notes.html" download>Download complete notes</a>`)+`<div class="domain-grid">${DATA.lessons.map((l,i)=>`<button class="domain" data-act="domain-reference" data-index="${i}"><strong>${esc(l.title)}</strong><p>${l.rows.length} reference topics · ${DATA.coverage[i].weight}% of scored content</p></button>`).join('')}</div><div class="pills"><button class="pill active" data-act="nav" data-to="learn">Scenario deep dives</button><button class="pill" data-act="nav" data-to="reference">Domain reference</button></div><div class="toolbar"><label class="search"><span class="sr">Find a topic</span><input id="topic-search" placeholder="Find a topic: RAG, recall, Model Cards…" value="${esc(query)}"></label><label><span class="sr">Domain</span><select id="domain-filter">${['all',1,2,3,4,5].map(v=>`<option value="${v}" ${String(domain)===String(v)?'selected':''}>${v==='all'?'All domains':DATA.domains[v-1]}</option>`).join('')}</select></label></div><div id="topics"></div>`);topics();}
function topics(){const list=DATA.concepts.filter(c=>(domain==='all'||c.domain===Number(domain))&&(`${c.label} ${c.meaning} ${c.when}`.toLowerCase().includes(query.toLowerCase())));$('#topics').innerHTML=`<div class="subhead"><h2>${domain==='all'?'Choose your next topic':esc(DATA.domains[Number(domain)-1])}</h2><span class="count">${list.length} deep dives</span></div><div class="grid">${list.map(c=>`<article class="card topiccard" data-act="nav" data-to="topic/${c.id}" role="link" tabindex="0"><div class="topic-top"><span class="tag">Domain ${c.domain}</span>${state.learned.includes(c.id)?'<span class="tag done">Understood</span>':''}</div><h3>${esc(c.label)}</h3><p>${esc(c.meaning)}</p><span class="small muted">6 scenarios · common confusions</span><button class="btn secondary small" data-act="nav" data-to="topic/${c.id}">Study this topic <span aria-hidden="true">→</span></button></article>`).join('')}</div>${!list.length?'<div class="card empty">No deep dive matches. Try the full reference notes for additional terms.</div>':''}`;}
function topic(id){const c=DATA.concepts.find(x=>x.id===id);if(!c){nav('learn');return;}const bank=[...DATA.concepts,...DATA.terms];frame('learn',`<button class="back" data-act="nav" data-to="learn">Back to topics</button>`+head(`Domain ${c.domain} · ${esc(DATA.domains[c.domain-1])}`,esc(c.label),esc(c.meaning),`<button class="btn ${state.learned.includes(id)?'light':'secondary'} small" data-act="learned" data-id="${id}">${state.learned.includes(id)?'Marked understood':'Mark understood'}</button>`)+`<div class="detail-layout"><div class="detail-main"><section class="card"><div class="eyebrow">When to use it</div><p>${esc(c.when)}</p><div class="callout warning"><strong>Easy mistake to avoid</strong><p>${esc(c.trap)}</p></div></section><h2>See it in six situations</h2><p class="muted small">Read the situation and predict the choice. Open it to see the reason.</p>${c.cases.map(([q,a],i)=>`<details class="case"><summary>Example ${i+1} · ${esc(q.split('.')[0].slice(0,90))}${q.split('.')[0].length>90?'…':''}</summary><div class="inside"><p>${esc(q)}</p><div class="callout"><span class="label">Best fit: ${esc(c.label)}</span>${esc(a)}</div></div></details>`).join('')}<section class="card" style="margin-top:25px"><h2>Why not the other choices?</h2>${c.distractors.map(id=>{const b=bank.find(z=>z.id===id);return `<div class="alt"><strong>${esc(b.label)}</strong><p>${esc(b.meaning)} Use it when: ${esc(b.when)}</p>${DATA.concepts.some(z=>z.id===id)?`<a class="small" href="#topic/${id}">Study this distinction</a>`:''}</div>`;}).join('')}</section></div><aside class="card detailaside"><div class="eyebrow">Your next step</div><h3>Apply the distinction</h3><p class="small muted">The new tests use these concepts in different scenarios. Explanations are available for every option.</p><button class="btn" data-act="nav" data-to="practice">Choose a test</button><hr style="border:0;border-top:1px solid var(--line);margin:22px 0"><strong class="small">Official scope</strong><a href="${esc(DATA.sources['domain'+c.domain])}" target="_blank" rel="noopener">AWS domain ${c.domain} objectives</a><a href="#reference">Open all reference notes</a></aside></div>`);}
function reference(){const lesson=DATA.lessons[lessonIndex]||DATA.lessons[0];frame('learn',head('Your full study reference','Study by exam domain','Exam topics organized by the five AWS AIF-C01 domains, with explanations and examples.',`<a class="btn secondary small" href="study-notes.html" download>Download notes</a>`)+`<div class="pills"><button class="pill" data-act="nav" data-to="learn">Scenario deep dives</button><button class="pill active" data-act="nav" data-to="reference">Domain reference</button></div><div class="toolbar"><label class="search"><span class="sr">Search all reference notes</span><input id="reference-search" value="${esc(referenceQuery)}" placeholder="Search all reference topics…"></label><label><span class="sr">Exam domain</span><select id="lesson-filter">${DATA.lessons.map((l,i)=>`<option value="${i}" ${i===lessonIndex?'selected':''}>${esc(l.title)}</option>`).join('')}</select></label></div><div id="reference-results"></div>`);referenceResults();}
function referenceResults(){const selected=referenceQuery?DATA.lessons:DATA.lessons.slice(lessonIndex,lessonIndex+1);let html='';let count=0;selected.forEach(l=>{const rows=l.rows.filter(r=>!referenceQuery||Object.values(r).join(' ').toLowerCase().includes(referenceQuery.toLowerCase()));if(!rows.length)return;count+=rows.length;html+=`<h2 style="margin-top:27px">${esc(l.title)}</h2><div class="tablewrap"><table><thead><tr><th>Topic</th><th>Simple explanation</th><th>Example</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${esc(r.topic)}</th><td>${esc(r.explanation)}</td><td>${esc(r.example)}</td></tr>`).join('')}</tbody></table></div>`;});$('#reference-results').innerHTML=html||'<div class="card empty">No matching reference topic. Try a shorter phrase or service name.</div>';}
function practice(){frame('practice',head('Ten full-length practice sets','Practice with a purpose','Choose a test to practise AWS AI concepts, then review your answers and explanations.')+`<div class="practice-settings"><label>Practice style <select class="select" id="mode-setting"><option value="study" ${state.settings.mode==='study'?'selected':''}>Learn as you go · untimed</option><option value="exam" ${state.settings.mode==='exam'?'selected':''}>Timed practice</option></select></label><label>Time allowance <select class="select" id="time-setting"><option value="90" ${state.settings.minutes===90?'selected':''}>90 minutes · standard</option><option value="120" ${state.settings.minutes===120?'selected':''}>120 minutes · with approved extension</option></select></label></div><div class="callout small"><strong>Review as you learn.</strong> Open an explanation when you need help. Questions marked “Review only” do not count toward your score.</div><div class="grid">${DATA.tests.map(t=>{const at=state.attempts[t.id],s=at?score(t,at):null;return `<article class="card testcard "><div class="flex spread"><span class="testno">PRACTICE TEST</span>${at?.finished?'<span class="tag done">Completed</span>':''}</div><h3>${esc(t.title)}</h3><p>AWS AI scenarios with detailed explanations for every answer option.</p><div class="testmeta"><span>65 questions</span><span>${t.questions.filter(q=>q.unscored).length?t.questions.filter(q=>q.unscored).length+' review-only questions':'All five exam domains'}</span></div><div class="progress"><span style="width:${s?s.answered/65*100:0}%"></span></div><div class="cardfoot"><span class="small muted">${at?.finished?'Est. score '+s.scaled+' / 1000':s?s.answered+' / 65 answered':'Not started'}</span><button class="btn small" data-act="start" data-test="${t.id}">${at?.finished?'Review result':at?'Resume':'Start test'}</button></div>${at?`<button class="back small" style="margin:17px 0 0" data-act="retake" data-test="${t.id}">Start a fresh attempt</button>`:''}</article>`;}).join('')}</div><p class="examnote">Practice results help identify topics to review; they do not predict an official exam result.</p>`);}
function start(id,retake=false){const t=getTest(id);if(!t)return;if(retake&&!confirm('Replace the saved attempt for this test? Your other tests and study progress will remain.'))return;if(!state.attempts[id]||retake){state.attempts[id]={answers:{},seen:{},flags:{},index:0,mode:state.settings.mode,remaining:state.settings.minutes*60,runningSince:null,finished:false};save();}nav(state.attempts[id].finished?`result/${id}`:`quiz/${id}`);if(location.hash===`#quiz/${id}`)render();}
function quiz(id){const t=getTest(id),at=state.attempts[id];if(!t||!at){nav('practice');return;}activeQuiz=String(id);if(at.mode==='exam'&&!at.finished&&!at.runningSince){at.runningSince=Date.now();save();}const q=t.questions[at.index],a=at.answers[q.id]||[],seen=!!at.revealed?.[q.id],s=score(t,at),readOnly=at.finished;let options='';
 if(q.type==='matching'||q.type==='ordering'){const prompts=q.type==='matching'?q.prompts:q.correct.map((_,i)=>`Step ${i+1}`);options=prompts.map((p,i)=>`<div class="matchrow"><label for="choice-${i}">${esc(p)}</label><select class="select" id="choice-${i}" data-position="${i}" data-qselect="1" ${readOnly?'disabled':''}><option value="-1">Choose an answer</option>${q.options.map((o,j)=>`<option value="${j}" ${a[i]===j?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`).join('');}
 else options=q.options.map((o,i)=>`<label class="option ${a.includes(i)?'selected':''} ${seen||readOnly?q.correct.includes(i)?'correct':a.includes(i)?'incorrect':'':''}"><input type="${q.type==='multi'?'checkbox':'radio'}" name="answer" data-answer="${i}" ${a.includes(i)?'checked':''} ${readOnly?'disabled':''}><span class="letter">${letters(i)}</span><span>${esc(o)}</span></label>`).join('');
 const type=q.type==='multi'?`Select ${q.correct.length===2?'TWO':q.correct.length===3?'THREE':q.correct.length}`:q.type==='matching'?'Match ALL pairs':q.type==='ordering'?'Put ALL steps in order':'Select ONE';
 frame('practice',`<button class="back" data-act="nav" data-to="${readOnly?'result/'+id:'practice'}">${readOnly?'Back to result':'Pause and return to tests'}</button><div class="quizlayout"><div><div class="card quizhead"><div class="flex spread"><div class="testtitle"><span class="bubble">${t.id}</span><div><strong>${esc(t.title)}</strong><div class="small muted">${esc(t.kind)}</div></div></div><span class="small">Question ${at.index+1} of 65</span></div><div class="progress"><span style="width:${(at.index+1)/65*100}%"></span></div></div><section class="card"><div class="flex spread" style="margin-bottom:21px"><span class="tag">${type}</span><span class="small muted">Domain ${q.domain} · ${esc(DATA.domains[q.domain-1])}</span></div>${q.unscored?'<div class="callout warning small"><strong>Source-key caveat.</strong> This uploaded question has ambiguous or outdated wording. It is review-only and will not affect your practice score. Open the explanation to see the correction.</div>':''}<h1 class="sr">Question ${at.index+1}</h1><div class="question">${esc(q.stem)}</div><fieldset style="padding:0;margin:0;border:0"><legend class="sr">${type}</legend>${options}</fieldset><div class="quizactions"><button class="btn secondary" data-act="prev" ${at.index===0?'disabled':''}>Previous</button><button class="btn light" data-act="explain" ${readOnly?'disabled':''}>${readOnly?'Explanation shown':seen?'Hide explanation':'Show explanation'}</button><button class="btn" data-act="next" ${at.index===64?'disabled':''}>Next question</button></div>${seen||readOnly?explanation(q,a,readOnly):''}</section></div><aside class="quizside"><div class="card"><div class="flex spread"><span class="small muted">${at.finished?'Review mode':at.mode==='exam'?'Time remaining':'Learning mode'}</span><span class="tag">${s.answered}/65</span></div><div class="timer" id="timer">${at.mode==='exam'?formatTime(elapsed(at)):'Untimed'}</div><button class="back small" style="margin:10px 0 0" data-act="flag">${at.flags[q.id]?'Unflag question':'Flag for review'}</button><div class="palette" aria-label="Question navigation">${t.questions.map((z,i)=>`<button class="qnum ${answered(z,at.answers[z.id])?'answered':''} ${at.flags[z.id]?'flagged':''} ${i===at.index?'current':''}" data-act="jump" data-index="${i}" aria-label="Question ${i+1}${at.flags[z.id]?', flagged':''}" ${i===at.index?'aria-current="step"':''}>${i+1}</button>`).join('')}</div><p class="tiny muted">Filled = answered<br>Gold underline = flagged</p><button class="btn dark" style="width:100%" data-act="finish">${at.finished?'View results':'Finish test'}</button><p class="tiny muted" style="margin:13px 0 0">${at.mode==='exam'?'The timer pauses when you leave this test.':'Open explanations whenever you need them.'} Progress saves on this browser.</p></div></aside></div>`);}
function formatTime(s){s=Math.max(0,s);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function explanation(q,a,review){let ans=q.type==='matching'?q.prompts.map((p,i)=>`${p}: ${q.options[q.correct[i]]}`).join('\n'):q.type==='ordering'?q.correct.map((v,i)=>`${i+1}. ${q.options[v]}`).join('\n'):q.correct.map(i=>letters(i)).join(', ');return `<section class="explanation" aria-label="Answer explanation"><h3>${q.unscored?'Review this question':answered(q,a)?correct(q,a)?'Your answer matches':'Let’s review the distinction':'Learn the reasoning'}</h3><p class="plain"><strong>${q.unscored?'Answer for discussion':'Correct answer'}:</strong> ${esc(ans)}</p>${q.audit?`<div class="callout warning"><strong>Correction / qualification</strong><p>${esc(q.audit)}</p></div>`:`<p>${esc(q.why)}</p>`}<h4>Every option explained</h4>${q.options.map((o,i)=>`<div class="explainoption"><strong>${letters(i)}. ${esc(o)} ${q.type==='single'||q.type==='multi'?q.correct.includes(i)?`<span class="tag done">${q.unscored?'Review note':'Best fit'}</span>`:'':''}</strong><p>${esc(q.explanations[i])}</p></div>`).join('')}${q.concept?`<p style="margin-top:20px"><a href="#topic/${q.concept}">Study this concept with six examples</a></p>`:''}${q.sourceExplanation?`<details style="margin-top:20px"><summary>Additional explanation</summary><p class="plain" style="margin-top:15px">${esc(q.sourceExplanation)}</p></details>`:''}${q.references?.length?`<details style="margin-top:17px"><summary>Reference links</summary>${[...new Set(q.references)].map((u,i)=>`<p class="small" style="margin-top:12px"><a href="${esc(u)}" target="_blank" rel="noopener">${esc(new URL(u).hostname)} · reference ${i+1}</a></p>`).join('')}</details>`:''}<p class="tiny muted" style="margin-top:18px">${review?'Reviewing a completed attempt does not change its recorded assisted count.':'Opening an explanation before finishing marks this question as assisted.'}</p></section>`;}
function finish(id,auto=false){const t=getTest(id),at=state.attempts[id];if(at.finished){nav('result/'+id);return;}const n=65-score(t,at).answered;if(!auto&&!confirm(n?`${n} question(s) are unanswered. Finish and score this attempt?`:'Finish and score this attempt?'))return;pause();at.finished=true;recordActivity('Completed test '+id+' · est. score '+score(t,at).scaled+' / 1000');at.finishedAt=new Date().toISOString();save();nav('result/'+id);}
function results(id){const t=getTest(id),at=state.attempts[id];if(!t||!at){nav('practice');return;}const s=score(t,at),raw=t.questions.filter(q=>correct(q,at.answers[q.id])).length,excluded=t.questions.filter(q=>q.unscored).length;frame('practice',`<button class="back" data-act="nav" data-to="practice">Back to all tests</button>`+head('Learn from the result',`${esc(t.title)} · your review`,'Use this result to choose what to study next. It is a practice estimate, not a prediction of your exam result.')+`<div class="card scorecard"><div class="scoregrid"><div><div class="eyebrow">Estimated scaled score</div><div class="scorebig">${s.scaled}<small> / 1000</small></div><span class="verdict ${s.scaled>=700?'pass':'fail'}">${s.scaled>=700?'At or above the 700 pass mark':'Below the 700 pass mark'}</span><p class="small muted" style="margin:14px 0 0">${s.right} of ${s.total} scored questions correct · ${s.percent}%</p></div><div class="gauge" role="img" aria-label="Score ${s.scaled} on a scale of 100 to 1000, pass mark 700"><div class="gaugebar"><span style="width:${(s.scaled-100)/9}%"></span><i style="left:66.67%"></i></div><div class="gaugelabels"><span>100</span><span class="passlabel">700 pass</span><span>1000</span></div></div></div><div class="stats"><div class="stat"><strong>${s.answered}/65</strong><span>Questions answered</span></div><div class="stat"><strong>${s.assisted}</strong><span>Scored questions with explanations opened</span></div><div class="stat"><strong>${excluded}</strong><span>Review-only questions</span></div></div>${excluded?`<p class="small muted">${excluded} review-only questions are excluded from this score. Read their explanations for the relevant qualifications.</p>`:''}<p class="small muted">AWS reports scores from 100 to 1000 and passes at 700. It does not publish its exact conversion, so this estimate maps your scored questions linearly (0 correct = 100, all correct = 1000). About 67% correct lands on 700. Review-only questions are excluded.</p><div class="flex"><button class="btn" data-act="review-test" data-test="${id}">Review every question</button><button class="btn secondary" data-act="retake" data-test="${id}">Start a fresh attempt</button></div></div><div class="subhead"><h2>Where to focus</h2></div><div class="tablewrap"><table><thead><tr><th>Domain</th><th>Correct / scored</th><th>Practice result</th></tr></thead><tbody>${DATA.domains.map((d,i)=>{const qs=t.questions.filter(q=>q.domain===i+1&&!q.unscored),r=qs.filter(q=>correct(q,at.answers[q.id])).length;return `<tr><th>${esc(d)}</th><td>${r} / ${qs.length}</td><td>${qs.length?Math.round(r/qs.length*100)+'%':'Review only'}</td></tr>`;}).join('')}</tbody></table></div><h2>Question review</h2><div class="card resultlist">${t.questions.map((q,i)=>`<div class="reviewrow"><div><span class="tag ${correct(q,at.answers[q.id])?'done':''}">${q.unscored?'Review only':!answered(q,at.answers[q.id])?'Unanswered':correct(q,at.answers[q.id])?'Correct':'Needs review'}</span><p>Q${i+1}. ${esc(q.stem.slice(0,130))}${q.stem.length>130?'…':''}</p></div><button class="btn secondary small" data-act="review-question" data-test="${id}" data-index="${i}">Review</button></div>`).join('')}</div>`);}
function review(){const items=[];DATA.tests.forEach(t=>{const at=state.attempts[t.id];if(!at)return;t.questions.forEach((q,i)=>{const wrong=answered(q,at.answers[q.id])&&!correct(q,at.answers[q.id])&&!q.unscored;const flag=at.flags[q.id];if(reviewFilter==='wrong'?wrong:reviewFilter==='flagged'?flag:at.seen[q.id])items.push({t,q,i});});});frame('review',head('Turn mistakes into understanding','Your review desk','Revisit missed answers, flagged questions and explanations you opened. Your practice stays on this browser.')+`<div class="pills">${[['wrong','Missed questions'],['flagged','Flagged for review'],['assisted','Explanation opened']].map(([k,l])=>`<button class="pill ${reviewFilter===k?'active':''}" data-act="review-filter" data-filter="${k}">${l}</button>`).join('')}</div><div class="card">${items.length?items.map(({t,q,i})=>`<div class="reviewrow"><div><span class="tag">Test ${t.id} · Q${i+1}</span><p>${esc(q.stem.slice(0,170))}${q.stem.length>170?'…':''}</p></div><button class="btn secondary small" data-act="review-question" data-test="${t.id}" data-index="${i}">Review</button></div>`).join(''):'<div class="empty"><h2>No questions here yet</h2><p class="muted">Complete some practice, or flag a question you want to revisit.</p><button class="btn" data-act="nav" data-to="practice">Choose a test</button></div>'}</div>`);}
function sources(){const names={guide:'Official AIF-C01 exam guide',domain1:'Domain 1: AI and ML',domain2:'Domain 2: Generative AI',domain3:'Domain 3: Foundation-model applications',domain4:'Domain 4: Responsible AI',domain5:'Domain 5: Security and governance',params:'Inference parameters',privacy:'Bedrock data protection',deploy:'SageMaker inference options',cards:'Model Card FAQs',governance:'SageMaker governance',policy:'AgentCore Policy',identity:'AgentCore Identity',quick:'Amazon Quick',kiro:'Kiro',strands:'Strands Agents',transform:'AWS Transform',comprehend:'Comprehend PII',qcost:'Q Developer cost analysis',qmodels:'Q Developer model selection',custom:'Custom-model on-demand deployment',eval:'Bedrock model evaluation',artifact:'Artifact notifications',amt:'AMT / Autotune configuration',learning:'SageMaker learning approaches',forecast:'Forecast availability'};frame('sources',head('AIF-C01','Exam guide & references','Review the exam domains and consult official AWS documentation.')+`<div class="tablewrap"><table><thead><tr><th>Exam domain</th><th>Weight</th><th>Study focus</th></tr></thead><tbody>${DATA.coverage.map(d=>`<tr><th>${esc(DATA.domains[d.domain-1])}</th><td>${d.weight}%</td><td>${esc(d.focus)}</td></tr>`).join('')}</tbody></table></div><section class="card"><h2>Exam essentials</h2><p>65 questions · 90 minutes standard time · Passing scaled score: 700 out of 1000.</p><p class="small muted">Use the 120-minute practice setting only if you have an approved 30-minute accommodation. Practice scores are estimates and separate from the official AWS scaled score.</p></section><div class="subhead"><h2>Official AWS documentation</h2></div><div class="sourcegrid">${Object.entries(DATA.sources).map(([k,u])=>`<a href="${esc(u)}" target="_blank" rel="noopener"><strong>${esc(names[k]||k)}</strong><div class="tiny muted">${esc(new URL(u).hostname)}</div></a>`).join('')}</div><p class="tiny muted">References reviewed: ${DATA.checked}.</p>`);}

function render(){if(!PROFILE_NAME){profileScreen();return;}pause();const parts=location.hash.slice(1).split('/'),page=parts[0]||'learn';if(page==='topic')topic(parts[1]);else if(page==='reference')reference();else if(page==='practice')practice();else if(page==='quiz')quiz(parts[1]);else if(page==='result')results(parts[1]);else if(page==='review')review();else if(page==='sources')sources();else learn();window.scrollTo(0,0);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(!b||b.disabled)return;const act=b.dataset.act;const id=activeQuiz;const at=id?state.attempts[id]:null;const t=id?getTest(id):null;const q=at?t.questions[at.index]:null;if(act==='domain-reference'){lessonIndex=Number(b.dataset.index);nav('reference');}else if(act==='nav')nav(b.dataset.to);else if(act==='domain'){domain=b.dataset.domain;learn();$('#topic-search').focus();}else if(act==='learned'){const cid=b.dataset.id;state.learned=state.learned.includes(cid)?state.learned.filter(v=>v!==cid):[...state.learned,cid];recordActivity((state.learned.includes(cid)?'Understood: ':'Reopened: ')+(DATA.concepts.find(c=>c.id===cid)?.label||cid));save();topic(cid);}else if(act==='start')start(b.dataset.test);else if(act==='retake')start(b.dataset.test,true);else if(act==='next'||act==='prev'||act==='jump'){at.index=act==='jump'?Number(b.dataset.index):at.index+(act==='next'?1:-1);save();quiz(id);window.scrollTo(0,0);}else if(act==='explain'){if(at.finished)return;at.seen[q.id]=true;at.revealed=at.revealed||{};at.revealed[q.id]=!at.revealed[q.id];save();quiz(id);if(at.revealed[q.id])$('.explanation')?.scrollIntoView({behavior:'smooth',block:'start'});}else if(act==='flag'){at.flags[q.id]=!at.flags[q.id];save();quiz(id);}else if(act==='finish')finish(id);else if(act==='review-test'){const a=state.attempts[b.dataset.test];a.index=0;save();nav('quiz/'+b.dataset.test);}else if(act==='review-question'){const a=state.attempts[b.dataset.test];a.index=Number(b.dataset.index);save();nav('quiz/'+b.dataset.test);}else if(act==='review-filter'){reviewFilter=b.dataset.filter;review();}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='domain-filter'){domain=el.value;topics();}else if(el.id==='lesson-filter'){lessonIndex=Number(el.value);referenceResults();}else if(el.id==='mode-setting'){state.settings.mode=el.value;save();}else if(el.id==='time-setting'){state.settings.minutes=Number(el.value);save();}else if(el.hasAttribute('data-answer')&&activeQuiz){const at=state.attempts[activeQuiz];if(at.finished)return;const q=getTest(activeQuiz).questions[at.index];const i=Number(el.dataset.answer);let a=at.answers[q.id]||[];at.answers[q.id]=q.type==='multi'?el.checked?[...new Set([...a,i])]:a.filter(x=>x!==i):[i];save();quiz(activeQuiz);}else if(el.dataset.qselect&&activeQuiz){const at=state.attempts[activeQuiz];if(at.finished)return;const q=getTest(activeQuiz).questions[at.index];const a=at.answers[q.id]||Array(q.correct.length).fill(-1);a[Number(el.dataset.position)]=Number(el.value);at.answers[q.id]=a;save();quiz(activeQuiz);}});
document.addEventListener('input',e=>{if(e.target.id==='topic-search'){query=e.target.value;topics();}if(e.target.id==='reference-search'){referenceQuery=e.target.value;referenceResults();}});
window.addEventListener('hashchange',render);window.addEventListener('pagehide',pause);
setInterval(()=>{if(!activeQuiz)return;const at=state.attempts[activeQuiz];if(!at||at.finished||at.mode!=='exam')return;const left=elapsed(at);const node=$('#timer');if(node)node.textContent=formatTime(left);if(left<=0)finish(activeQuiz,true);},1000);
render();

document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches&&e.target.matches('article[data-act]'))e.target.click();});
